insert into public.pontos_latentes_textos (ponto_latente, titulo, sintese, potencias_instrucao, o_que_por_tras, como_aparece_instrucao, por_que_agora, caminho_desenvolvimento, para_refletir, para_compreender_instrucao, para_aplicar_instrucao, para_avancar) values
  ('captar', 'CAPTAR — Demanda e fluxo de novos pacientes', 'Existe necessidade de fortalecer a entrada de novos pacientes para que a clínica dependa menos de movimentos pontuais, indicação espontânea ou períodos de maior procura.', 'Já existe uma prática clínica em movimento. O relatório deve destacar somente potências confirmadas nas respostas, como pacientes ativos, canais que já geram procura, parcerias existentes, público definido ou ações que já trouxeram retorno.', 'A captação pode estar acontecendo sem um processo claro: poucos canais ativos, ações descontínuas, dependência de indicação ou ausência de acompanhamento sobre de onde chegam os pacientes.', 'Personalizar com evidências reais do diagnóstico: canais utilizados, frequência de procura, número de pacientes ativos, origem dos contatos, parcerias e outras respostas pertinentes. Não afirmar ausência ou dependência se isso não estiver demonstrado.', 'Sem alguma previsibilidade de entrada, decisões sobre agenda, receita e crescimento ficam mais dependentes do acaso e mais difíceis de planejar.', 'Identificar os canais que já apresentam sinais de resposta, escolher poucas ações de aquisição coerentes com o público e acompanhar sua execução e resultado.', 'Hoje, você sabe quais ações realmente colocam novos pacientes em contato com a sua clínica?', 'Manual: direcionar para o capítulo validado sobre público, posicionamento/captação, conforme mapeamento final.', 'Ferramenta: indicar somente após validação do mapa Ponto Latente → ferramenta.', 'Meu Plano de Ação de 30 dias.'),
  ('precificar', 'PRECIFICAR — Sustentação financeira do atendimento', 'Há sinais de que a forma de precificar, reajustar ou organizar financeiramente os serviços merece atenção para que o trabalho clínico também sustente a própria clínica.', 'Destacar dados positivos reais: agenda ativa, receita existente, conhecimento de custos, prática de reajuste, meta definida, organização financeira ou outros elementos efetivamente respondidos.', 'O valor praticado pode ter sido definido principalmente por referências externas, histórico ou percepção do que o paciente consegue pagar, sem integrar todos os elementos econômicos da clínica.', 'Personalizar com faturamento, preço da sessão, custos, retirada, capacidade, reajustes e metas somente quando esses dados estiverem presentes no diagnóstico.', 'Mais atendimentos não significam necessariamente maior sustentabilidade. Sem conhecer a relação entre preço, custos, capacidade e retirada, a clínica pode aumentar esforço sem aumentar resultado na mesma proporção.', 'Compreender a estrutura econômica da clínica, revisar valores e critérios de reajuste e conectar preço à capacidade e às metas reais.', 'O valor que você pratica hoje sustenta a clínica que deseja construir ou apenas mantém sua agenda funcionando?', 'Manual: capítulo validado de Serviços e Precificação.', 'Ferramenta: Calculadora de Valor da Sessão, quando a regra final indicar precificação.', 'Meu Plano de Ação de 30 dias.'),
  ('posicionar', 'POSICIONAR — Clareza de posicionamento', 'O trabalho clínico existe, mas pode haver espaço para tornar mais claro para quem ele é, qual necessidade atende e por que alguém escolheria esse trabalho.', 'Destacar somente forças identificadas: experiência, público já atendido, especializações, reconhecimento, indicações, comunicação existente ou diferenciais explicitados.', 'O posicionamento pode ter sido construído mais a partir da formação e dos serviços oferecidos do que da combinação entre público, necessidade, proposta de valor e forma de comunicação.', 'Usar respostas reais sobre público, nicho, comunicação, canais, diferenciais e origem dos pacientes. Evitar afirmar que a psicóloga ''não sabe se posicionar'' sem evidência.', 'Quando o valor do trabalho não está claro, captação e precificação podem ficar mais difíceis, mesmo quando a qualidade clínica já existe.', 'Organizar público, proposta de valor, diferenciais e comunicação para que a clínica seja compreendida com mais clareza por quem pode se beneficiar dela.', 'Quando alguém conhece seu trabalho pela primeira vez, consegue entender com clareza para quem ele é e o valor que ele oferece?', 'Manual: direcionar para o capítulo validado de posicionamento/público.', 'Ferramenta: indicar após validação do mapa de ferramentas.', 'Meu Plano de Ação de 30 dias.'),
  ('produto_mix', 'PRODUTO / MIX — Concentração no atendimento individual', 'A clínica pode estar excessivamente concentrada no atendimento individual, fazendo com que receita e crescimento dependam diretamente da quantidade de sessões realizadas.', 'Destacar serviços já existentes além do individual, competências que podem sustentar novos formatos, demanda percebida, experiência com grupos/supervisão/cursos ou outros dados reais.', 'É comum que a clínica cresça inicialmente pela sessão individual. Com o tempo, esse formato pode se tornar praticamente toda a operação, mesmo quando existem conhecimentos e demandas que permitiriam outros serviços.', 'Personalizar com percentual ou quantidade de receita/agenda por serviço, carga semanal, serviços existentes e capacidade. Não afirmar concentração sem suporte dos dados.', 'Uma clínica muito concentrada em um único formato fica mais exposta a oscilações de agenda e encontra um limite natural na quantidade de horas disponíveis.', 'Avaliar quais serviços fazem sentido para o público e para a experiência profissional antes de simplesmente adicionar produtos. O objetivo é coerência de portfólio, não quantidade.', 'Se você não pudesse aumentar sua quantidade de sessões individuais, de onde poderia vir o próximo avanço da sua clínica?', 'Manual: capítulo validado sobre serviços/modelo de negócio.', 'Ferramenta: Calculadora de Grupo quando houver indicação real para formato grupal; outras ferramentas dependem de validação.', 'Meu Plano de Ação de 30 dias.'),
  ('esteira', 'ESTEIRA — Ampliação e organização do modelo de serviços', 'Há sinais de que a clínica pode organizar melhor a relação entre seus serviços para criar caminhos de continuidade e diferentes formas de entrega de valor.', 'Destacar serviços já existentes, procura recorrente, público definido, grupos, supervisões, cursos, parcerias ou outras bases que realmente apareçam nas respostas.', 'À medida que novos serviços surgem, eles podem permanecer como iniciativas isoladas. A questão deixa de ser apenas ''o que mais posso vender?'' e passa a ser como as ofertas se conectam de maneira coerente.', 'Personalizar com serviços atuais, recorrência, origem da receita, capacidade e comportamento do público. Não sugerir uma nova oferta específica sem base.', 'Sem organização, ampliar serviços pode aumentar complexidade sem aumentar sustentabilidade. Uma esteira deve simplificar a jornada e o modelo econômico.', 'Organizar o portfólio, identificar a função de cada serviço e definir quais ofertas devem atrair, aprofundar ou dar continuidade ao relacionamento com o público.', 'Seus serviços hoje formam um caminho coerente para o cliente ou funcionam como ofertas independentes?', 'Manual: capítulo validado sobre serviços/modelo de negócio/receitas.', 'Ferramenta: indicar depois da validação do mapa Ponto Latente → ferramenta.', 'Meu Plano de Ação de 30 dias.'),
  ('escalar', 'ESCALAR — Expansão sustentável', 'A clínica apresenta elementos que podem permitir expansão, mas o crescimento precisa preservar capacidade, qualidade, organização e sustentabilidade financeira.', 'Destacar somente evidências de maturidade existentes: demanda consistente, agenda organizada, margem, serviços validados, processos, recorrência ou capacidade disponível.', 'Quando uma clínica começa a funcionar melhor, pode surgir a tendência de crescer apenas aumentando agenda, lançando novos serviços ou assumindo mais compromissos. Escala exige que a estrutura suporte o avanço.', 'Personalizar com capacidade máxima, ocupação, receita, mix, demanda, processos e demais indicadores disponíveis. Não afirmar que a pessoa está pronta para escalar enquanto a regra metodológica final não confirmar isso.', 'Crescer sem estrutura pode transformar aumento de receita em aumento proporcional de carga, complexidade e dependência da profissional.', 'Antes de expandir, verificar o que já está validado, quais processos precisam ser fortalecidos e qual crescimento pode ocorrer sem reproduzir a mesma dependência de horas.', 'O próximo crescimento da sua clínica depende de trabalhar mais ou de organizar melhor aquilo que já funciona?', 'Manual: capítulo validado sobre crescimento/sustentação.', 'Ferramenta: somente após validação metodológica; não associar automaticamente a uma ferramenta.', 'Meu Plano de Ação de 30 dias.')
